describe('Background Job Toast Notification', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
    cy.clearLocalStorage();
    cy.clearCookies();
  });

  it('should display a toast notification when background job completes successfully', () => {
    cy.get('[data-testid="start-job-button"]').click();

    cy.get('[data-testid="job-status"]').should('contain', 'Processing');

    cy.get('[role="alert"]', { timeout: 10000 }).should('be.visible');
    cy.get('[role="alert"]').should('contain', 'Job completed successfully');

    cy.get('[role="alert"]').should('have.class', 'toast-success');
  });

  it('should display error toast when background job fails', () => {
    cy.get('[data-testid="start-job-button"]').click();
    cy.get('[data-testid="job-type-select"]').select('error-job');
    cy.get('[data-testid="start-job-button"]').click();

    cy.get('[role="alert"]', { timeout: 10000 }).should('be.visible');
    cy.get('[role="alert"]').should('contain', 'Job failed');
    cy.get('[role="alert"]').should('have.class', 'toast-error');
  });

  it('should auto-dismiss toast notification after 5 seconds', () => {
    cy.get('[data-testid="start-job-button"]').click();

    cy.get('[role="alert"]', { timeout: 10000 }).should('be.visible');
    cy.get('[role="alert"]').should('contain', 'Job completed successfully');

    cy.get('[role="alert"]', { timeout: 6000 }).should('not.exist');
  });

  it('should allow manual dismissal of toast notification', () => {
    cy.get('[data-testid="start-job-button"]').click();

    cy.get('[role="alert"]', { timeout: 10000 }).should('be.visible');
    cy.get('[data-testid="toast-close-button"]').click();

    cy.get('[role="alert"]').should('not.exist');
  });

  it('should display multiple toasts for concurrent background jobs', () => {
    cy.get('[data-testid="start-job-button"]').click();
    cy.get('[data-testid="start-job-button"]').click();

    cy.get('[role="alert"]', { timeout: 10000 }).should('have.length', 2);
    cy.get('[role="alert"]').first().should('contain', 'Job completed successfully');
    cy.get('[role="alert"]').last().should('contain', 'Job completed successfully');
  });

  it('should handle rapid successive job submissions without losing notifications', () => {
    for (let i = 0; i < 3; i++) {
      cy.get('[data-testid="start-job-button"]').click();
      cy.wait(500);
    }

    cy.get('[role="alert"]', { timeout: 10000 }).should('have.length.at.least', 1);
    cy.get('[role="alert"]').first().should('be.visible');
  });
});
